from gurobipy import GRB

def solve(env):
    m = gp.Model(env=env)
    processing_times = [4, 5, 3, 6, 2, 5, 4, 3]
    reentrant_orders = {1, 4}
    capacity = [15, 18, 12]
    cost = [30, 25, 35]

    x = m.addVars(8, 3, name="x", vtype=GRB.BINARY)

    # Objective: minimize total operating cost
    obj = gp.quicksum(
        (gp.quicksum(
            (processing_times[i] * (2 if i in reentrant_orders else 1)) * x[i, t]
            for i in range(8)
        )) * cost[t]
        for t in range(3)
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Constraint: each order assigned to exactly one truck
    m.addConstrs((x.sum(i, '*') == 1 for i in range(8)), name="assign")

    # Constraint: truck capacity not exceeded
    m.addConstrs(
        (gp.quicksum(
            (processing_times[i] * (2 if i in reentrant_orders else 1)) * x[i, t]
            for i in range(8)
        ) <= capacity[t] for t in range(3)),
        name="capacity"
    )

    m.optimize()

    if m.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={m.objVal}")
