from gurobipy import GRB

def solve_problem(env):
    model = gp.Model(env=env)

    zones = ['A', 'B', 'C']
    vans = [1, 2]

    demand = {
        'A': 120,
        'B': 120,
        'C': 90
    }

    dispatch_cost = {1: 300, 2: 320}
    max_battery_capacity = {1: 150, 2: 180}
    operational_coefficient = {1: 0.08, 2: 0.07}

    x = model.addVars(vans, zones, name="x", lb=0, ub=GRB.INFINITY, vtype=GRB.INTEGER)
    y = model.addVars(vans, name="y", vtype=GRB.BINARY)

    for z in zones:
        model.addConstr(gp.quicksum(x[v, z] for v in vans) == demand[z], name=f"zone_demand_{z}")

    for v in vans:
        model.addConstr(gp.quicksum(x[v, z] for z in zones) <= max_battery_capacity[v], name=f"van_capacity_{v}")

    M = 180
    for v in vans:
        for z in zones:
            model.addConstr(x[v, z] <= M * y[v], name=f"van_zone_capacity_{v}_{z}")

    model.setObjective(
        gp.quicksum(dispatch_cost[v] * y[v] for v in vans) +
        gp.quicksum(operational_coefficient[v] * x[v, z] ** 2 for v in vans for z in zones),
        GRB.MINIMIZE
    )

    model.optimize()

    if model.status == GRB.OPTIMAL:
        print(f"FINAL_OBJECTIVE={model.objVal}")
